    "passage_cn": "环境问题与工业化的进展有关。在英国（UK）的工业革命（産業革命）时期，以化石燃料为动力源的生产活动开始真正展开。此后，煤炭、石油等化石燃料的使用不断增加，这在促进工业化进展和经济增长的同时，也引发了大气污染、土壤污染等问题。\n20世纪后半叶，越境污染扩大后，这类问题作为全球环境问题在国际社会中受到关注。联合国大会（UN General Assembly）为应对这一课题，决定于1972年在瑞典（Sweden）的斯德哥尔摩（Stockholm）召开国际会议。\n1997年通过的《京都议定书》首次向发达国家规定了具体的温室气体减排目标。但是，《京都议定书》没有向金砖国家（BRICS）等增长显著的新兴国家规定具体的数值目标。首个要求包括发展中国家在内的所有缔约方努力减排的国际协定，是2016年生效的《巴黎协定》（Paris Agreement）。",
