    "passage_cn": "现在的荷兰（オランダ，Netherlands），其起源是：1568年对统治此地的西班牙（Spain）发动叛乱的7个州，于1581年宣布作为尼德兰联邦共和国（Republic of the Seven United Netherlands）独立。\n从17世纪到18世纪初，荷兰是正在兴起的全球经济的中心。值得一提的是，荷兰于1602年设立了被称为世界最早股份公司的荷兰东印度公司（Dutch East India Company），又于1609年设立了近年被评价为世界最早中央银行的阿姆斯特丹银行（Bank of Amsterdam）。荷兰还是所谓实行锁国政策（鎖国政策）的江户时代的日本唯一建立通商关系的西方国家。\n20世纪中叶过后，荷兰苦于被称为“荷兰病”（オランダ病）的经济低迷。由于国内的能源资源被大规模开发，其出口的迅速增加导致本国货币升值，以制造业为首的出口产业陷入困境。然而，自1980年代以后，荷兰推进旨在实现灵活而稳定的劳动力市场的政策，重新恢复了经济的活力。现在的荷兰经济以其高度的开放性和生产率而闻名。\n在政治方面，荷兰被视为与英国（UK）式的两大政党政党政治划清界限的、多极共存型民主（多極共存型デモクラシー）的典型例子。荷兰虽是小国，但设有国际法院（ICJ）和欧洲司法组织（Eurojust）等，在国际政治中也发挥着重要作用。",
    "expl_cn": "③荷兰阿姆斯特丹周边是一片围垦地（圩田，ポルダー），国土约四分之一在海拔零米以下。剖面图③描绘了在100km以东海拔降到0m以下（接近-20m）的低平地，符合阿姆斯特丹的特征。",
