    "passage": "⟦1:現在のオランダ⟧（Netherlands）は，この地を支配していたスペイン（Spain）に対して1568年に反乱を起こした7州が，1581年にネーデルラント連邦共和国（Republic of the Seven United Netherlands）として独立を宣言したことに，その起源を有する。\n17世紀から18世紀初頭にかけて，オランダは勃興するグローバル経済の中心であった。世界最初の株式会社と言われるオランダ東インド会社（Dutch East India Company）を1602年に，さらに世界最初の中央銀行とも近年評されるアムステルダム銀行（Bank of Amsterdam）を1609年に設立したことは特筆に値する。オランダはまた，いわゆる⟦2:鎖国政策をとる江戸時代の日本が通商関係を結んだ唯一の西洋の国⟧でもあった。\n20世紀半ば過ぎになると「オランダ病」と呼ばれる経済の低迷に苦しんだ。国内の⟦3:エネルギー資源⟧が大規模に開発された結果，その急速な輸出増大が自国通貨高をもたらし，製造業をはじめとする輸出産業が苦境に陥ったのである。しかし，1980年代以降，柔軟かつ安定した労働市場の実現に向けた政策を推し進め，経済のダイナミズムを取り戻していった。現在のオランダ経済は，その高い開放性と生産性で知られている。\n政治の面では，イギリス（UK）型の二大政党による政党政治とは一線を画す，多極共存型デモクラシーの典型例とされてきた。オランダは小国でありながら，⟦4:国際司法裁判所（ICJ）⟧や欧州司法機構（Eurojust）が置かれるなど，国際政治においても重要な役割を担っている。",
