    "passage_cn": "水泥（セメント）作为混凝土和砂浆的材料被广泛使用。其主要原料石灰石分布在日本各地，全国有200多个石灰石矿山在运营。\n水泥的历史悠久，古埃及（Egypt）和古罗马（Rome）已经将其用作建材。像现在这样广泛使用，始于工业革命时期的英国（UK）。这一时期，能在更短时间内凝固的水泥制法的开发取得了进展。在日本，1875年在官营工厂（官営工場）开始制造，1881年在石灰石丰富的山口县诞生了首家民营水泥公司。\n目前，日本的水泥产业与电力业、钢铁业一样排放大量温室气体，这被视为一大课题。为此，面向温室气体减排（温室効果ガス排出削減）正在推进各种研发。另一方面，在有石灰岩的地区，有时能看到被称为喀斯特地形（カルスト地形）的独特地形和景观，不少地方成为重要的旅游资源。能看到日本最大级喀斯特地形的山口县秋吉台，其地下约100m处延展着名为秋芳洞的钟乳洞，每年吸引超过20万游客。",
