    "passage_cn": "现代社会的形态在很大程度上依赖于交通、通信技术。特别是19世纪以后交通、通信方面的技术革新给世界带来了巨大影响。工业革命时期的19世纪前半叶，蒸汽船和蒸汽机车的实用化取得进展。这些发明与运河网的扩大、道路的改良等交通环境的飞跃式发展被称为交通革命，对帝国主义（帝国主義）也产生了不小的影响。\n19世纪后半叶到20世纪前半叶，通信网络发展，开始进行国际通信。20世纪前半叶，飞机的实用化取得进展，第二次世界大战后，许多人开始跨越大海往来于不同地区。这些交通、通信的发展推动了经济活动的全球化（経済活動のグローバル化）。\n20世纪末，互联网开始在全世界普及。互联网的发展使世界变得便利的同时，对隐私权（プライバシーの権利）的意识也提高了，处理个人信息时要求谨慎。",
